def QuantumBlockEncoding.StoredGivens.Run.bind : {α β : Type} → Run α → (α → Run β) → Run β :=
fun {α β} x f =>
  have y := f x.value;
  { value := y.value, cost := x.cost + y.cost }
def QuantumBlockEncoding.StoredGivens.collect : {α : Type} → {n : ℕ} → (Fin n → Run α) → Run (Vector α n) :=
fun {α} {n} f =>
  have entries := Vector.ofFn f;
  { value := Vector.map Run.value entries,
    cost := (fun op => ∑ i, entries[↑i].cost op) + n • (2 • tick Op.read + 2 • tick Op.write) }
def QuantumBlockEncoding.StoredGivens.materialize : {N M : ℕ} → (Fin N → Fin M → Run ℝ) → Run (StoredMatrix N M) :=
fun {N M} f => collect fun i => collect (f i)
def QuantumBlockEncoding.StoredThinLQ.entry : {N M : ℕ} → StoredMatrix N M → Fin N → Fin M → Run ℝ :=
fun {N M} A i j => do
  let row ← StoredGivens.read A i
  StoredGivens.read row j
def QuantumBlockEncoding.StoredTensorTrain.sumEntries : {k : ℕ} → (Fin k → Run ℝ) → Run ℝ :=
fun x x_1 => Nat.brecOn (motive := fun x => (Fin x → Run ℝ) → Run ℝ) x sumEntries._f x_1
